package sctp
import("bufio";"encoding/binary";"encoding/json";"io";"net";"os";"testing")
func TestSourceCurrentStreamPolicyObserver(t *testing.T){
 input,err:=os.Open(os.Getenv("GO_SCTP_POLICY_INPUTS"));if err!=nil{t.Fatal(err)};defer input.Close();output,err:=os.Create(os.Getenv("GO_SCTP_POLICY_OUTPUT"));if err!=nil{t.Fatal(err)};defer output.Close();enc:=json.NewEncoder(output);scan:=bufio.NewScanner(input)
 for scan.Scan(){var c struct{ID string `json:"id"`;Selector string `json:"selector"`;InitialKind string `json:"initial_kind"`;InitialValue uint32 `json:"initial_value"`;Operation string `json:"operation"`;ReplacementKind string `json:"replacement_kind"`;ReplacementValue uint32 `json:"replacement_value"`};if err=json.Unmarshal(scan.Bytes(),&c);err!=nil{t.Fatal(err)}
 left,right:=net.Pipe();cfg,err:=buildClientConfig(WithNetConn(left),WithMTU(1228),WithFastRtxWnd(3000));if err!=nil{t.Fatal(err)};a:=createAssociationFromConfigWithTsn(cfg,1);a.useForwardTSN=true;a.setState(established);a.cumulativeTSNAckPoint=0;s:=a.createStream(0,false)
 kind:=func(name string)byte{switch name{case"reliable":return ReliabilityTypeReliable;case"rexmit":return ReliabilityTypeRexmit;default:t.Fatal("source input policy");return 0}};s.SetReliabilityParams(false,kind(c.InitialKind),c.InitialValue);chunks,_:=s.packetize(make([]byte,300),PayloadTypeWebRTCBinary);if len(chunks)!=1{t.Fatal("real packetizer",len(chunks))};a.pendingQueue.push(chunks[0]);a.lock.Lock();a.movePendingDataChunkToInflightQueue(a.pendingQueue.peek());a.lock.Unlock()
 if c.Operation=="remove"{a.lock.Lock();a.unregisterStream(s,io.EOF);a.lock.Unlock()}else if c.Operation=="set"{s.SetReliabilityParams(false,kind(c.ReplacementKind),c.ReplacementValue)}else{t.Fatal(c.Operation)}
 var packets[][]byte;a.lock.Lock();var consumed bool;if c.Selector=="fast"{chunks[0].missIndicator=3;a.willRetransmitFast=true;packets=a.gatherOutboundFastRetransmissionPackets(nil,nil,&consumed)}else if c.Selector=="rto"{a.setCWND(20000);a.setRWND(20000);a.inflightQueue.markAllToRetrasmit();for _,packet:=range a.getDataPacketsToRetransmit(nil,&consumed){wire,err:=a.marshalPacket(packet);if err!=nil{t.Fatal(err)};packets=append(packets,wire)}}else{t.Fatal(c.Selector)};_,present:=a.streams[0];a.lock.Unlock()
 sizes:=[]int{};tsns:=[]uint32{};for _,packet:=range packets{sizes=append(sizes,len(packet));for off:=12;off<len(packet);{if off+4>len(packet){t.Fatal("short chunk")};size:=int(binary.BigEndian.Uint16(packet[off+2:off+4]));if size<4||off+size>len(packet){t.Fatal("bad chunk")};if packet[off]==0{if size<16{t.Fatal("short DATA")};tsns=append(tsns,binary.BigEndian.Uint32(packet[off+4:off+8]))};off+=(size+3)&^3}}
 head:=chunks[0];if head.head!=nil{head=head.head};if err=enc.Encode(map[string]any{"id":c.ID,"selector":c.Selector,"operation":c.Operation,"sent":chunks[0].nSent,"abandoned":chunks[0].abandoned(),"raw":head._abandoned,"packet_sizes":sizes,"transmitted_tsn":tsns,"stream_present":present});err!=nil{t.Fatal(err)};_=a.close();_=right.Close()
 };if err=scan.Err();err!=nil{t.Fatal(err)}
}
